      !contract ||
      !positive(contract.targetId) ||
      !positive(contract.createdNight) ||
      contract.createdNight < 2 ||
      contract.id !== `servant:night:${contract.createdNight}` ||
      contract.expiresNight !== contract.createdNight + 1
