      ended &&
      ["cleared", "expired", "target_dead"].includes(ended.kind as string) &&
      positive(ended.day) &&
      ended.day >= contract.createdNight &&
      ended.day <= Number(contract.expiresNight) &&
      (ended.kind !== "expired" || ended.day === contract.expiresNight)
