  commitNoble(next: NobleState): void {
    writeState(this.nobleState, next);
    // 写字段已经发生；stringify 失败时旧影子保持，外层尚未继续 lease／知识或目标绑定提交。
    this.#nobleJson = JSON.stringify(next);
