        owner.contracts.set(
          `servant:night:${day}`,
          Object.freeze({
            target,
            createdNight: day,
            expiresNight: day + 1,
            id: `servant:night:${day}`,
          }),
        );
      return Object.freeze({
        actorId: owner.noble.id,
